		if !okIdent {
			return nil, nil, trace.BadParameter("expected selector identifier, got: %T", f.X)
		}
		fnName := fmt.Sprintf("%s.%s", id.Name, f.Sel.Name)
		fn, err := p.getFunction(fnName)
		return fn, callExpr.Args, trace.Wrap(err)
