func TestExpressionInterpolate(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name   string
		input  string
		traits map[string][]string
		want   []string
	}{
		{"bare literal", "  production  ", nil, []string{"production"}},
		{"dot variable and whitespace", "  {{  internal.logins  }}  ", map[string][]string{"logins": {"alice", "bob"}}, []string{"alice", "bob"}},
		{"bracket variable", `{{external["email address"]}}`, map[string][]string{"email address": {"alice@example.com"}}, []string{"alice@example.com"}},
		{"prefix and suffix", "  IAM#{{internal.logins}};  ", map[string][]string{"logins": {"alice", "bob"}}, []string{"IAM#alice;", "IAM#bob;"}},
		{"email local", `{{email.local(external.email)}}`, map[string][]string{"email": {"Alice <alice@example.com>", "bob@example.com"}}, []string{"alice", "bob"}},
		{"nested calls", `user-{{regexp.replace(email.local(external.email), "^([^.]+)\\..*$", "$1")}}`, map[string][]string{"email": {"alice.smith@example.com", "bob.jones@example.com"}}, []string{"user-alice", "user-bob"}},
		{"constant replace source", `{{regexp.replace("foo-bar", "^foo-(.*)$", "$1")}}`, nil, []string{"bar"}},
		{"constant email source", `{{email.local("Alice <alice@example.com>")}}`, nil, []string{"alice"}},
		{"quoted whitespace retained", `{{regexp.replace(" a ", "^ a $", "hit")}}`, nil, []string{"hit"}},
		{"unmatched values omitted", `{{regexp.replace(internal.logins, "^foo-(.*)$", "$1")}}`, map[string][]string{"logins": {"bad", "foo-alice", "foo-bob"}}, []string{"alice", "bob"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			expr, err := NewExpression(tt.input)
			require.NoError(t, err)
			values, err := expr.Interpolate(tt.traits)
			require.NoError(t, err)
			require.Equal(t, tt.want, values)
		})
	}
}

func TestExpressionValidation(t *testing.T) {
	t.Parallel()
	tests := []string{
		"internal.foo}}", "{{internal.foo", "{{internal.foo}}}", "{{{{internal.foo}}}}", "{{}}",
		"{{internal}}", "{{internal.}}", "{{internal.foo.bar}}", `{{internal["foo"]["bar"]}}`,
		`{{internal.foo["bar"]}}`, "{{internal[123]}}", `{{"asdf"}}`, "{{123}}", "{{unknown.foo}}",
		`{{regexp.unknown("foo")}}`, "{{email.local()}}", `{{email.local("a@b", "c@d")}}`,
		`{{regexp.replace("foo", "f")}}`, `{{regexp.replace("foo", "f", "b", "x")}}`,
		`{{regexp.replace(external.foo, external.pattern, "x")}}`,
		`{{regexp.replace(external.foo, "f", external.replacement)}}`,
		`{{regexp.replace("foo", "[", "x")}}`,
		`{{email.local(regexp.match("foo"))}}`,
		`{{regexp.replace(regexp.match("foo"), "f", "b")}}`,
		`{{regexp.match("foo")}}`,
	}
	for _, input := range tests {
		t.Run(input, func(t *testing.T) {
			_, err := NewExpression(input)
			require.Error(t, err)
			require.True(t, trace.IsBadParameter(err), "%v", err)
		})
	}
}

func TestExpressionEvaluationErrors(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name   string
		input  string
		traits map[string][]string
		bad    bool
		text   string
	}{
		{"missing trait", "{{external.email}}", nil, false, "external.email"},
		{"empty trait", "{{external.email}}", map[string][]string{"email": {}}, false, "no values"},
		{"empty values cannot gain prefix", "pre{{external.email}}post", map[string][]string{"email": {""}}, false, "no values"},
		{"replacement with no matches", `{{regexp.replace(external.email, "^x", "y")}}`, map[string][]string{"email": {"alice@example.com"}}, false, "no values"},
		{"empty email", "{{email.local(external.email)}}", map[string][]string{"email": {""}}, true, "empty"},
		{"malformed email", "{{email.local(external.email)}}", map[string][]string{"email": {"not an address"}}, true, "address"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			expr, err := NewExpression(tt.input)
			require.NoError(t, err)
			values, err := expr.Interpolate(tt.traits)
			require.Empty(t, values)
			require.Error(t, err)
			if tt.bad {
				require.True(t, trace.IsBadParameter(err), "%v", err)
			} else {
				require.True(t, trace.IsNotFound(err), "%v", err)
			}
			require.Contains(t, err.Error(), tt.text)
		})
	}
}

func TestExpressionVariableValidation(t *testing.T) {
	t.Parallel()
	expr, err := NewExpression(`{{regexp.replace(email.local(external.email), "^(.+)$", "$1")}}`)
	require.NoError(t, err)
	var gotNamespace, gotName string
	values, err := expr.Interpolate(map[string][]string{"email": {"alice@example.com"}}, func(namespace, name string) error {
		gotNamespace, gotName = namespace, name
		return nil
	})
	require.NoError(t, err)
	require.Equal(t, []string{"alice"}, values)
	require.Equal(t, "external", gotNamespace)
	require.Equal(t, "email", gotName)

	_, err = expr.Interpolate(map[string][]string{"email": {"alice@example.com"}}, func(namespace, name string) error {
		return trace.BadParameter("disallowed %s.%s", namespace, name)
	})
	require.True(t, trace.IsBadParameter(err), "%v", err)
	require.Contains(t, err.Error(), "disallowed external.email")
}

func TestMatcher(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name  string
		input string
		yes   []string
		no    []string
	}{
		{"plain literal", "foo.bar", []string{"foo.bar"}, []string{"xfoo.bar", "fooXbar", "foo.barx"}},
		{"wildcard", "foo*bar", []string{"foobar", "foo-baz-bar"}, []string{"xfoo-bar", "foo-barx"}},
		{"raw regex", "^foo[0-9]+$", []string{"foo1", "foo123"}, []string{"foo", "xfoo1"}},
		{"positive predicate", `{{regexp.match("foo")}}`, []string{"foo", "xfoox"}, []string{"bar"}},
		{"negative predicate", `{{regexp.not_match("foo")}}`, []string{"bar"}, []string{"foo", "xfoox"}},
		{"prefix suffix", `pre-{{regexp.match("^mid$")}}-post`, []string{"pre-mid-post"}, []string{"pre-mid-x-post", "xpre-mid-post", "pre-mid-postx"}},
		{"negative prefix suffix", `pre-{{regexp.not_match("^bad$")}}-post`, []string{"pre-good-post"}, []string{"pre-bad-post", "bad"}},
		{"boolean composition", `{{regexp.match("foo") && !regexp.match("bar")}}`, []string{"foo", "xfoox"}, []string{"bar", "foobar"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matcher, err := NewMatcher(tt.input)
			require.NoError(t, err)
			for _, in := range tt.yes {
				require.True(t, matcher.Match(in), "%q should match %q", tt.input, in)
			}
			for _, in := range tt.no {
				require.False(t, matcher.Match(in), "%q should not match %q", tt.input, in)
			}
		})
	}
}

func TestMatcherValidation(t *testing.T) {
	t.Parallel()
	tests := []string{
		`{{regexp.match("foo")`, `regexp.match("foo")}}`, `{{regexp.unknown("foo")}}`,
		`{{regexp.match("[")}}`, `{{regexp.match()}}`, `{{regexp.match("foo", "bar")}}`,
		`{{regexp.match(external.pattern)}}`, `{{regexp.match(email.local("foo@example.com"))}}`,
