	}
	for _, input := range tests {
		t.Run(input, func(t *testing.T) {
			_, err := NewMatcher(input)
			require.Error(t, err)
			require.True(t, trace.IsBadParameter(err), "%v", err)
		})
	}
}

func TestExpressionDepthIsBounded(t *testing.T) {
	t.Parallel()
	input := "internal.foo"
	for i := 0; i < 1200; i++ {
		input = "email.local(" + input + ")"
	}
	_, err := NewExpression("{{" + input + "}}")
	require.Error(t, err)
	require.True(t, trace.IsBadParameter(err) || trace.IsLimitExceeded(err), "%v", err)
}

func TestExpressionNonStringErrorIncludesInput(t *testing.T) {
	t.Parallel()
	input := `{{regexp.match("secret")}}`
	_, err := NewExpression(input)
	require.Error(t, err)
