	"github.com/gravitational/trace"
	"github.com/vulcand/predicate"

	"github.com/gravitational/teleport/lib/utils"
)

const (
	// LiteralNamespace identifies values that do not require trait lookup.
	LiteralNamespace = "literal"
	// EmailNamespace identifies email functions.
	EmailNamespace = "email"
	// EmailLocalFnName identifies email.local.
	EmailLocalFnName = "local"
	// RegexpNamespace identifies regular expression functions.
	RegexpNamespace      = "regexp"
	RegexpMatchFnName    = "match"
	RegexpNotMatchFnName = "not_match"
	RegexpReplaceFnName  = "replace"

	// These bounds are checked before invoking the predicate parser, which
	// recursively descends into Go syntax trees.
	maxExpressionDepth  = 128
	maxExpressionLength = 64 * 1024
)

// Expression is a string expression with optional fixed text around it.
type Expression struct {
	expr           Expr
	prefix, suffix string
}

// Namespace returns the namespace of the first variable, or literal for a
// constant expression. It is retained for callers of the earlier API.
func (e *Expression) Namespace() string {
	if variable, ok := firstVariable(e.expr); ok {
